const products = [
 {id:'whey',name:'Whey Protein Concentrado',category:'Proteínas',detail:'900 g · Chocolate',price:12990,color:'#faa21a',label:'WHEY<br>PROTEIN.',size:'900g',tag:'Essencial'},
 {id:'creatina',name:'Creatina Monohidratada',category:'Creatinas',detail:'300 g · Sem sabor',price:7990,color:'#e7e5d9',label:'CREA<br>TINE.',size:'300g',tag:'Sua rotina'},
 {id:'pre',name:'Pré-treino Energy',category:'Pré-treinos',detail:'300 g · Frutas vermelhas',price:9990,color:'#bfbdc9',label:'PRE<br>WORKOUT.',size:'300g',tag:'Em destaque'},
 {id:'vitaminas',name:'Multivitamínico Daily',category:'Vitaminas',detail:'60 cápsulas',price:4990,color:'#c4ce9e',label:'DAILY<br>VITAMINS.',size:'60 caps',tag:'Dia a dia'},
 {id:'isolado',name:'Whey Protein Isolado',category:'Proteínas',detail:'900 g · Baunilha',price:18990,color:'#d9d3bb',label:'WHEY<br>ISOLATE.',size:'900g',tag:'Proteínas'},
 {id:'creatina150',name:'Creatina Monohidratada',category:'Creatinas',detail:'150 g · Sem sabor',price:4990,color:'#d6a56b',label:'CREA<br>TINE.',size:'150g',tag:'Essencial'},
 {id:'coqueteleira',name:'Coqueteleira Atletic',category:'Acessórios',detail:'600 ml · Preto',price:2990,color:'#a3aaa4',label:'SHAKE<br>& GO.',size:'600ml',tag:'Com você'},
 {id:'omega',name:'Ômega 3',category:'Vitaminas',detail:'60 cápsulas',price:5990,color:'#91adba',label:'OMEGA<br>THREE.',size:'60 caps',tag:'Sua rotina'}
];
const categories=['Todos','Proteínas','Creatinas','Pré-treinos','Vitaminas','Acessórios'];
const $=s=>document.querySelector(s), money=v=>(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
let stored=read('atletic.cart',{}),cart={};
if(stored && typeof stored==='object')for(const p of products){let qty=stored[p.id];if(Number.isInteger(qty)&&qty>0)cart[p.id]=Math.min(qty,99)}
let coupon=read('atletic.coupon',false)===true,category='Todos',toastTimer;
const preferred=read('atletic.theme',null);document.body.classList.toggle('dark',preferred==='dark'||(!preferred&&matchMedia('(prefers-color-scheme: dark)').matches));
function updateTheme(){const dark=document.body.classList.contains('dark');$('#theme').setAttribute('aria-label',dark?'Ativar modo claro':'Ativar modo escuro');$('#theme').setAttribute('aria-pressed',String(dark))}updateTheme();
$('#theme').onclick=()=>{document.body.classList.toggle('dark');save('atletic.theme',document.body.classList.contains('dark')?'dark':'light');updateTheme()};
function bottle(p){return `<div class="bottle" style="--pack:${p.color}"><div class="lid"></div><div class="label"><small>ATLETIC</small><strong>${p.label}</strong><span>ILUSTRAÇÃO</span><b>${p.size}</b></div></div>`}
$('#categories').innerHTML=categories.map((c,i)=>`<button class="cat" data-category="${c}"><div class="cat-image" aria-hidden="true">${i?bottle(products[[0,0,1,2,3,6][i]]):'<span>↗</span>'}</div>${c==='Todos'?'Ver tudo':c}</button>`).join('');
$('#filters').innerHTML=categories.map(c=>`<button data-category="${c}" class="${c==='Todos'?'active':''}">${c}</button>`).join('');
function normalize(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function renderProducts(){let term=normalize($('#search').value.trim()),list=products.filter(p=>(category==='Todos'||p.category===category)&&normalize(p.name+' '+p.detail+' '+p.category).includes(term));let sort=$('#sort').value;if(sort==='asc')list.sort((a,b)=>a.price-b.price);if(sort==='desc')list.sort((a,b)=>b.price-a.price);$('#resultCount').textContent=`${list.length} produtos`;$('#empty').hidden=!!list.length;$('#products').innerHTML=list.map(p=>`<article class="product"><div class="product-art"><span class="tag">${p.tag}</span><div aria-hidden="true">${bottle(p)}</div></div><p class="type">${p.category}</p><h3>${p.name}</h3><p class="detail">${p.detail}</p><div class="buy-row"><span class="price">${money(p.price)}</span><button class="add" data-add="${p.id}" aria-label="Adicionar ${p.name} ${p.detail} ao carrinho">+</button></div></article>`).join('');document.querySelectorAll('#filters button').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category))})}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function renderCart(){save('atletic.cart',cart);save('atletic.coupon',coupon);const items=products.filter(p=>cart[p.id]);const count=items.reduce((sum,p)=>sum+cart[p.id],0),subtotal=items.reduce((sum,p)=>sum+p.price*cart[p.id],0),discount=coupon?Math.round(subtotal*.1):0;$('#count').textContent=count;$('#drawerCount').textContent=`(${count})`;$('#cartItems').innerHTML=items.length?items.map(p=>`<div class="cart-line"><div class="mini" aria-hidden="true">${bottle(p)}</div><div><h3>${p.name}</h3><p>${p.detail}</p><div class="qty"><button data-qty="${p.id}" data-change="-1" aria-label="Diminuir ${p.name}">−</button><span>${cart[p.id]}</span><button data-qty="${p.id}" data-change="1" aria-label="Aumentar ${p.name}">+</button></div></div><div><strong>${money(p.price*cart[p.id])}</strong><br><button class="remove" data-remove="${p.id}">Remover</button></div></div>`).join(''):'<p class="empty-cart">Sua sacola está esperando suas escolhas.<br>Explore o catálogo e adicione seus essenciais.</p>';$('#subtotal').textContent=money(subtotal);$('#discount').textContent='− '+money(discount);$('#total').textContent=money(subtotal-discount);$('#checkout').disabled=!count;$('#removeCoupon').hidden=!coupon;$('#couponMessage').textContent=coupon?'ATLETIC10 aplicado: 10% de desconto demonstrativo.':'Teste o cupom demonstrativo ATLETIC10.';$('#checkoutMessage').textContent=''}
document.addEventListener('click',e=>{const c=e.target.closest('[data-category]');if(c){category=c.dataset.category;renderProducts();if(c.closest('#categories'))$('#catalog').scrollIntoView({behavior:'smooth'})}const a=e.target.closest('[data-add]');if(a){cart[a.dataset.add]=Math.min((cart[a.dataset.add]||0)+1,99);renderCart();toast('Produto adicionado à sacola')}const q=e.target.closest('[data-qty]');if(q){const id=q.dataset.qty;cart[id]=Math.min(cart[id]+Number(q.dataset.change),99);if(cart[id]<=0)delete cart[id];renderCart()}const r=e.target.closest('[data-remove]');if(r){delete cart[r.dataset.remove];renderCart()}});
$('#search').addEventListener('input',renderProducts);$('#searchForm').onsubmit=e=>{e.preventDefault();$('#catalog').scrollIntoView({behavior:'smooth'})};$('#sort').onchange=renderProducts;
$('#cartOpen').onclick=()=>{$('#cart').showModal();document.body.style.overflow='hidden'};function closeCart(){$('#cart').close()}$('#cartClose').onclick=closeCart;$('#cart').addEventListener('close',()=>{document.body.style.overflow='';$('#cartOpen').focus()});$('#cart').addEventListener('click',e=>{if(e.target===$('#cart')){const r=$('#cart').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)closeCart()}});
$('#couponForm').onsubmit=e=>{e.preventDefault();if(!Object.keys(cart).length){$('#couponMessage').textContent='Adicione um produto antes de aplicar o cupom.';return}if($('#coupon').value.trim().toUpperCase()==='ATLETIC10'){coupon=true;renderCart()}else $('#couponMessage').textContent='Cupom não encontrado. Para testar, use ATLETIC10.'};$('#removeCoupon').onclick=()=>{coupon=false;renderCart()};$('#checkout').onclick=()=>{$('#checkoutMessage').textContent='Esta é uma prévia. A finalização da compra será conectada à plataforma utilizada pela Atletic. Nenhum pedido foi enviado.'};$('#year').textContent=new Date().getFullYear();renderProducts();renderCart();
